const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod } = require('@expo/config-plugins');

// This is an Expo-managed project -- `android/` doesn't exist in source, it's
// regenerated by `expo prebuild` every time. So, exactly like
// `with-dynamic-launcher-splash.js` does for the bootsplash logo, the banner
// PNGs live under the committed `assets/` folder and get copied into the
// freshly-generated `android/app/src/main/res/` during prebuild -- there's
// nothing under `android/` to drop them into directly.
const BANNER_DENSITIES = ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi'];
const BANNER_FILENAME = 'tv_banner.png';

const copyBannerResources = (projectRoot, resRoot) => {
  const sourceRoot = path.join(projectRoot, 'assets', 'android', 'tv-banner');
  for (const density of BANNER_DENSITIES) {
    const bucket = `drawable-${density}`;
    const sourceFile = path.join(sourceRoot, bucket, BANNER_FILENAME);
    if (!fs.existsSync(sourceFile)) {
      // Don't hard-fail the whole prebuild over a missing density -- just
      // skip it, same as it would be skipped if the asset were never added.
      continue;
    }
    const targetDir = path.join(resRoot, bucket);
    fs.mkdirSync(targetDir, { recursive: true });
    fs.copyFileSync(sourceFile, path.join(targetDir, BANNER_FILENAME));
  }
};

const withTVBannerResources = (config) =>
  withDangerousMod(config, [
    'android',
    async (modConfig) => {
      const projectRoot = modConfig.modRequest.projectRoot;
      const resRoot = path.join(projectRoot, 'android', 'app', 'src', 'main', 'res');
      copyBannerResources(projectRoot, resRoot);
      return modConfig;
    },
  ]);

const withTVManifest = (config) =>
  withAndroidManifest(config, async (config) => {
    const androidManifest = config.modResults.manifest;

    if (!androidManifest['uses-feature']) {
      androidManifest['uses-feature'] = [];
    }

    // Touchscreen is not required for TV
    androidManifest['uses-feature'].push({
      $: {
        'android:name': 'android.hardware.touchscreen',
        'android:required': 'false',
      },
    });

    // Declare Leanback software support
    androidManifest['uses-feature'].push({
      $: {
        'android:name': 'android.software.leanback',
        'android:required': 'false',
      },
    });

    // Reference the Leanback launcher banner. `withTVBannerResources` above
    // is what actually puts res/drawable-*/tv_banner.png in place -- without
    // that step this reference would point at nothing.
    androidManifest.application[0].$['android:banner'] = '@drawable/tv_banner';

    // Add LEANBACK_LAUNCHER category to MainActivity
    const mainActivity = androidManifest.application[0].activity.find(
      (a) => a.$['android:name'] === '.MainActivity'
    );

    if (mainActivity) {
      if (!mainActivity['intent-filter']) {
        mainActivity['intent-filter'] = [];
      }
      mainActivity['intent-filter'].push({
        action: [{ $: { 'android:name': 'android.intent.action.MAIN' } }],
        category: [{ $: { 'android:name': 'android.intent.category.LEANBACK_LAUNCHER' } }],
      });
      mainActivity.$['android:screenOrientation'] = 'sensorLandscape';
    }

    return config;
  });

module.exports = function withAndroidTV(config) {
  config = withTVManifest(config);
  config = withTVBannerResources(config);
  return config;
};
